for inp in inputs:
    result = inp
    for pattern, replacement in rules:
        result = result.replace(pattern, replacement)
    test_results.append(result)

print("Testing rules:")
for i, (inp, out, res) in enumerate(zip(inputs, ['efhdxz', 'cwh', 'xw', 'hidk', 'wiukb'], test_results)):
    status = "✓" if res == out else "✗"
    print(f"  {status} '{inp}' -> '{res}' (expected: '{out}')")

